// === ⚙️ CONFIGURATION ===
const inputData = items[0].json;
const {
    config,
    session_state: sessionState = {},  // state: contains a flat dictionary of misc. variables
    session_events: sessionEvents = [],  // history: contains list of {author, task, parts[text, inlineData, fileData, functionCall, functionResponse], actions[], partial, timestamp} objs
    prompt_author: promptAuthor = "system",  // used if another agent directly wrote the prompt
    PHASE_ID: currentPhaseId,
    TASK_ID: currentTaskId,
    AGENT_ID: providedAgentId,
    base64_img_string,  // If we have an input image
    base64_img_string_mime,
	debug_system,
	debug_prompt,
	debug_response,
    ...externalVars
} = inputData;
Object.assign(sessionState, externalVars);  // Other variables into sessionState. If same name exists, overwritten.
if (!config) throw new Error("CONFIGURATION ERROR: No 'config' object found in the payload.");
if (!config.tasks || !config.agents) throw new Error("CONFIGURATION ERROR: The provided 'config' is missing 'tasks' or 'agents' registries.");

// agent & task
if (!currentTaskId) throw new Error("No TASK_ID provided to the Universal Agent.");
const taskBlueprint = config.tasks[currentTaskId];
if (!taskBlueprint) throw new Error(`Task ID '${currentTaskId}' not found in config.`);
const targetAgentId = providedAgentId || taskBlueprint.assigned_agent;
const agentBlueprint = config.agents[targetAgentId];
if (!agentBlueprint) throw new Error(`Agent ID '${targetAgentId}' not found in config.`);

// === 🎯 MODEL CAPABILITY IDENTIFICATION ===
const modelType = taskBlueprint.model_type || agentBlueprint.model_type || "text"; // Supports "text", "view_img", "img2img"
const isImageRead = (modelType === "view_img") || (modelType === "img2img");
const isImageGen = (modelType === "img2img");
const outputType = isImageGen ? "image_blob" : "json";  //  constrained generation produces json, no raw text case atm
const resolvedProvider = taskBlueprint.provider || agentBlueprint.provider ||
    config.provider_by_type[modelType] || "google";

// === 🪶 String Templating (The ADK Way) ===
function templateInstruction(instruction, state) {
    if (!instruction) return "";
    return instruction.replace(/{([^}]+)}/g, (match, rawKey) => {
        const key = rawKey.trim();
        let val = state[key];
        if (val === undefined) throw new Error(`TEMPLATE ERROR: The variable '{${key}}' was referenced in the prompt, but it does not exist in the session_state.`);
        if (typeof val === 'object') return JSON.stringify(val);  // If the variable is an array/object (like {master_table}), we stringify it so it renders as text in the prompt.
        return val;
    });
}

// Recursively template the string leaves of a config value (used by no_model results).
// Strings get {var} substitution; objects/arrays recurse; numbers/booleans/null pass through.
function templateObject(value, state) {
    if (typeof value === 'string') return templateInstruction(value, state);
    if (Array.isArray(value)) return value.map(v => templateObject(v, state));
    if (value && typeof value === 'object') {
        const out = {};
        for (const [k, v] of Object.entries(value)) out[k] = templateObject(v, state);
        return out;
    }
    return value;
}

// === 📝 CONSTRUCT SYSTEM & USER PROMPTS ===
const finalSystemInstruction = templateInstruction(agentBlueprint.system_identity, sessionState);
const finalUserInstruction = templateInstruction(taskBlueprint.instruction, sessionState);

// === 📦 Construct empty API Payload ===
let requestBody = {
    contents: []  // contains list of {role, parts[text, inlineData, fileData, functionCall, functionResponse]} objs
};  // systemInstruction{}, generationConfig{} & safetySettings[] are the other optional fields
if (finalSystemInstruction) {
    requestBody.systemInstruction = { parts: [{ text: finalSystemInstruction }] };
}
if (outputType === "json" && taskBlueprint.schema) {  // constrained generation - json schema
    requestBody.generationConfig = {
        response_mime_type: "application/json",
        response_schema: taskBlueprint.schema
    };
}

// === 📜 HISTORY SCOPE RESOLUTION & CONSTRUCTION ===
const rawHistoryScope = taskBlueprint.history_scope || agentBlueprint.history_scope || [];  // A list of agent IDs
const historyScope = Array.isArray(rawHistoryScope) ? rawHistoryScope : [rawHistoryScope];  // Allow single item as string

// Response events: in scope iff their author is listed (unchanged behavior).
// Prompt events (author "user"/"system") are paired with the event immediately after
// them in the log (their reply). A prompt is replayed iff its reply survived the filter
// AND one of these holds:
//   a) the reply is the CURRENT agent's own — always include, even when "system" isn't
//      in the scope list. This keeps the agent's past model turns properly paired with
//      the instructions that elicited them (ADK replays user prompts verbatim; without
//      this, self-history replays as unprompted answers).
//   b) the prompt's author is explicitly in scope (the original opt-in rule for
//      replaying other conversations' prompts).
// Prompts whose turn crashed (successor missing or itself a prompt) are excluded.
// Scoped-out prompts leave adjacent same-role replies, which flushQueue already squashes.
const PROMPT_AUTHORS = ["user", "system"];
const filteredEvents = sessionEvents.filter((event, i) => {
    if (PROMPT_AUTHORS.includes(event.author)) {
        const next = sessionEvents[i + 1];
        const replyInScope = !!next && historyScope.includes(next.author) && !PROMPT_AUTHORS.includes(next.author);
        if (!replyInScope) return false;
        return next.author === targetAgentId || historyScope.includes(event.author);
    }
    return historyScope.includes(event.author);
});

// === 🖼️️️ FINISH CONSTRUCTING CURRENT PROMPT ===
const currentParts = [{ text: finalUserInstruction }];
if (isImageRead && base64_img_string && base64_img_string_mime) {
    currentParts.unshift({ // unshift adds the element to the front of the array
        inlineData: {
            mimeType: base64_img_string_mime,
            data: base64_img_string
        }
    });
}
const currentPromptEvent = {
    author: promptAuthor,
    parts: currentParts
};

// === 🔄 QUEUE PROCESSING & CONTENT FLUSHING ===
const eventsToProcess = [...filteredEvents, currentPromptEvent];
const finalContents = [];
let queue = [];
let currentIsModel = null; // true if targetAgentId (model), false otherwise (user)

// Parts pulled from the LOG are sanitized: any inlineData.data is a placeholder tag
// (<IMAGE_BLOB...>), not real base64. Replaying that verbatim would send Gemini an invalid
// blob, so we rewrite the part into a plain text marker instead. Returning a {text} part
// (rather than handling this at push time) lets the marker fall through the normal text
// path below, so it inherits author labeling like any other text - otherwise an image-only
// event (common for img2img responses, which carry no text part) would replay unattributed.
// Live blobs never reach here: they only enter via currentPromptEvent, which is unsanitized.
const resolveLogPart = (part, isModelPart) => {
    const blob = part.inlineData || part.inline_data;
    if (blob && typeof blob.data === "string" && blob.data.startsWith("<IMAGE_BLOB")) {
        return { text: isModelPart ? "[image generated here - omitted from history]"
                                   : "[image omitted from history]" };
    }
    return part; // text, functionCall, functionResponse, fileData, live inlineData: untouched
};

// n8n persists the event log as JSON, so a logged model reply is one JSON *string* — every
// newline inside its field values escaped to the two-character sequence \n. The LLM must
// never see that escaping: whenever a replayed text part parses as a JSON object/array,
// re-render it as readable "key: value" text with real newlines restored. Anything that
// isn't pure JSON (live instructions, image markers, fenced text) fails the shape check
// or the parse and passes through verbatim.
const renderJsonValue = (val) => {
    if (typeof val === "string") return val;                              // raw — real newlines
    if (val === null || typeof val !== "object") return String(val);
    if (Array.isArray(val)) return val.map(renderJsonValue).join("\n");   // separator BETWEEN items only: 1 item ⇒ no newline
    return Object.entries(val).map(([k, v]) => {
        const r = renderJsonValue(v);
        return r.includes("\n") ? `${k}:\n${r}` : `${k}: ${r}`;           // multi-line values start under their key
    }).join("\n");
};
const restoreJsonText = (text) => {
    if (typeof text !== "string") return text;
    const t = text.trim();
    const looksJson = (t.startsWith("{") && t.endsWith("}")) || (t.startsWith("[") && t.endsWith("]"));
    if (!looksJson) return text;
    try { return renderJsonValue(JSON.parse(t)); } catch (e) { return text; }
};

const flushQueue = () => {
    if (queue.length === 0) return;

    const isModelQueue = currentIsModel;
    const role = isModelQueue ? "model" : "user";
    const contentParts = [];

    // Determine if we need to apply author labels based on your rules
    let applyLabels = false;
    if (!isModelQueue) {
        const uniqueAuthors = new Set(queue.map(e => e.author));

        if (queue.length === 1) {
            const author = queue[0].author;
            // Single item: apply if author isn't a standard 'system' or 'user'
            applyLabels = author !== "system" && author !== "user";
        } else {
            const allSame = uniqueAuthors.size === 1;
            const onlyAuthor = Array.from(uniqueAuthors)[0];
            // Multiple items: apply unless ALL are 'system' or ALL are 'user'
            applyLabels = !(allSame && (onlyAuthor === "system" || onlyAuthor === "user"));
        }
    }

    // Process the queue items into standard Gemini parts
    let pushedAnyText = false; // across the queue: gates separators so the FIRST item never gets a leading newline
    queue.forEach((event) => {
        // The LIVE self-prompt stays unlabeled: the agent doesn't reliably know its own
        // registry name, so "[<own id>] said:" would read as a third party's words. This
        // forfeits the label-as-boundary for this one event, which is acceptable only
        // because it is always the FINAL event of the request — nothing follows it to
        // need delimiting. Replayed copies in later turns are unaffected (they surface
        // as model turns, which are never labeled anyway).
        const suppressLabel = event === currentPromptEvent && event.author === targetAgentId;
        let firstTextOfEvent = true;
        event.parts.forEach((rawPart) => {
            // Swap sanitized image placeholders for text BEFORE the text/non-text split,
            // so markers get labeled and prefixed exactly like real text.
            const part = resolveLogPart(rawPart, isModelQueue);
            if (part.text !== undefined) {
                // Restore logged JSON to readable text (real newlines) before the LLM sees it.
                let text = restoreJsonText(part.text);
                if (firstTextOfEvent) {
                    // ADK-style bracketed attribution, task-qualified so an agent that ran
                    // several tasks — or the same task across a retry loop — replays as
                    // distinguishable events. (The live prompt event carries no task field
                    // and falls back to author-only.) No "For context:" opener: with all
                    // events squashed into one content, it could be read as applying to the
                    // final (live) instruction too, and we have no unambiguous delimiter.
                    // Every event boundary also gets a plain "\n" separator — 2+ events
                    // only, never before the first — so UNLABELED squashed events (e.g.
                    // adjacent model-turn JSON replies) can't run together as {...}{...}.
                    const label = (applyLabels && !suppressLabel)
                        ? `[${event.author}${event.task ? " · " + event.task : ""}] said: `
                        : "";
                    text = (pushedAnyText ? "\n" : "") + label + text;
                    firstTextOfEvent = false;
                }
                pushedAnyText = true;
                contentParts.push({ text });
            } else {
                // Push inlineData, functionCall, functionResponse, etc., completely untouched
                contentParts.push(part);
            }
        });
    });

    finalContents.push({ role, parts: contentParts });
    queue = []; // Empty the queue for the next batch
};

const forceFlatten = (modelType === "img2img") && resolvedProvider === "openai";
// Process events sequentially into the queue
for (const event of eventsToProcess) {
    // GUARD: the LIVE prompt is always the user turn eliciting this response, even when
    // prompt_author === targetAgentId (an agent prompting itself). Without this it would
    // classify as a model turn, and the request would end on role "model" — rejected by
    // Gemini. Replayed in FUTURE turns the same event correctly surfaces as a model event
    // and merges with its adjacent reply (self-talk: "I should do X" ... does X).
    const isModel = forceFlatten ? false : (event !== currentPromptEvent && event.author === targetAgentId);
    // If the role switches (and the queue isn't empty), flush the existing queue
    if (currentIsModel !== null && isModel !== currentIsModel) {
        flushQueue();
    }
    currentIsModel = isModel;
    queue.push(event);
}
flushQueue(); // Flush the final segment (this inherently handles the currentPromptEvent and any attached images)
if (finalContents.length > 0 && finalContents[0].role === "model") {
    finalContents.unshift({ role: "user", parts: [{ text: "..." }] }); // Gemini requires the first content to have role "user"
}
requestBody.contents = finalContents; // Finally, attach the constructed contents to the request payload

// === 🧾 LOG THE PROMPT AS A SESSION EVENT ===
// ADK style: the prompt is itself an immutable event in the transcript. Without it, the
// persisted log would contain only model-authored response events, and the next turn's
// QUEUE PROCESSING could never reconstruct alternating user/model Gemini history.
// We append a SANITIZED copy (image blob swapped for a tag, mirroring Node 3's replacer);
// the raw currentPromptEvent above keeps the real blob for the requestBody only.
// NOTE: .push() mutates, but that's required here - sessionEvents is a const destructure,
// and this local copy is ours to build before returning. Appended AFTER filteredEvents was
// computed, so the current prompt can't be double-included in this turn's own contents.
function sanitizeEventParts(key, value) {  // same replacer as Node 3's sanitize()
    if (typeof value === "string" && value.length > 100) {
        if (key === "data" && (this.mimeType || this.mime_type)) return "<IMAGE_BLOB(Gemini)>";
        if (key === "b64_json") return "<IMAGE_BLOB(OpenAI)>";
        if (key === "base64_img_string") return "<IMAGE_BLOB>";
        if (key === "thoughtSignature") return "<THOUGHT_SIGNATURE>";
    }
    return value;
}

sessionEvents.push({
    author: promptAuthor,
    task: currentTaskId,
    status: "ok",
    parts: JSON.parse(JSON.stringify(currentPromptEvent.parts, sanitizeEventParts)),
    timestamp: new Date().toISOString()
});

// === 🏎️ TIER, ROUTING & NO_MODEL RESOLUTION ===
// Task tier overrides agent tier, which falls back to the type-based default.
let requestedTier = taskBlueprint.model_tier || agentBlueprint.model_tier ||
                    (isImageGen ? config.default_image_tier : config.default_text_tier);

let model_url;
let skipApi = false;
let noModelResult = null; // canned task result, only populated in no_model mode

if (requestedTier === "no_model") {
    // === ⚡ NO_MODEL MODE: skip the API, resolve the canned result locally ===
    skipApi = true;
    model_url = "no_model";

    // A task supplies its canned payload as `result` OR `textResult` (result wins if
    // both). Both are objects of named fields, templated identically and merged into
    // sessionState identically — the choice only controls how Node 3 logs the event:
    //   result     → JSON.stringify (field names carry the structure)
    //   textResult → plain text: "<name>: <value>" lines; a single field logs just
    //                its value, name omitted
    const rawResult = taskBlueprint.result !== undefined ? taskBlueprint.result : taskBlueprint.textResult;
    if (rawResult === undefined) {
        throw new Error(`CONFIGURATION ERROR: Task '${currentTaskId}' requested tier 'no_model' but defines no 'result' or 'textResult'.`);
    }
    // result/textResult is an object; we template its string leaves, so there is no JSON to escape or parse.
    noModelResult = templateObject(rawResult, sessionState);

} else {
    // === 🏎️ TIER CAPPING (honor user speed/cost ceiling from April) ===
    const tierRanks = { "fast": 1, "medium": 2, "slow": 3 };
    const maxTier = isImageGen ? (config.maximum_image_tier || "slow") : (config.maximum_text_tier || "slow");
    if (tierRanks[requestedTier] && tierRanks[maxTier] && tierRanks[requestedTier] > tierRanks[maxTier]) {
        requestedTier = maxTier;
    }

// === 🌐 DYNAMIC URL RESOLUTION (provider → type → tier) ===
    let model_name = null;  // OpenAI carries the model in the request BODY; the URL is shared across tiers
    let model_quality = null;         // OpenAI `quality`: low|medium|high|auto (config-driven, see registry)
    let model_input_fidelity = null;  // OpenAI `input_fidelity`: low|high
    try {
        const registryEntry = config.model_registry[resolvedProvider][modelType][requestedTier];
        if (!registryEntry) throw new Error("URL resolved to undefined.");
        // Registry entries: bare URL string (Gemini) OR { url, model, quality, input_fidelity }
        // (OpenAI, where every tier hits the same endpoint and the tier is expressed entirely
        // through the body params).
        model_url = typeof registryEntry === "object" ? registryEntry.url : registryEntry;
        model_name = typeof registryEntry === "object" ? (registryEntry.model || null) : null;
        model_quality = typeof registryEntry === "object" ? (registryEntry.quality || null) : null;
        model_input_fidelity = typeof registryEntry === "object" ? (registryEntry.input_fidelity || null) : null;
        if (!model_url) throw new Error("URL resolved to undefined.");
    } catch (e) {
        throw new Error(`ROUTING ERROR: Failed to resolve model URL. Provider: '${resolvedProvider}', Type: '${modelType}', Tier: '${requestedTier}'.`);
    }

    // === 🎨 OPENAI PAYLOAD OVERRIDE (img2img via /v1/images/edits) ===
    if (resolvedProvider === "openai") {
        if (!isImageGen) {
            throw new Error(`ROUTING ERROR: OpenAI provider currently supports model_type 'img2img' only (task '${currentTaskId}' asked for '${modelType}').`);
        }
        // QUEUE PROCESSING ran in forceFlatten mode, so requestBody.contents is exactly ONE
        // labeled user turn containing the scoped history + current prompt. Translate it:
        //   text parts            → joined into the single `prompt` string
        //   live inlineData parts → data-URL entries in `images` (log placeholders were
        //                           already rewritten to text markers by resolveLogPart)
        //   systemInstruction     → no OpenAI equivalent; prepended to the prompt
        const flatParts = requestBody.contents[0]?.parts || [];
        const promptPieces = [];
        const inputImages = [];
        for (const part of flatParts) {
            if (part.text !== undefined) promptPieces.push(part.text);
            const blob = part.inlineData || part.inline_data;
            if (blob?.data && !blob.data.startsWith("<IMAGE_BLOB")) {
                inputImages.push({ image_url: `data:${blob.mimeType || blob.mime_type || "image/png"};base64,${blob.data}` });
            }
        }
        const flatPrompt = [finalSystemInstruction, promptPieces.join("\n")].filter(Boolean).join("\n\n");

        requestBody = {
            ...(model_name ? { model: model_name } : {}),  // Node 3's cost lookup reads requestBody.model
            prompt: flatPrompt,
            ...(inputImages.length ? { images: inputImages } : {}),
            // Pinned per tier in the registry. Unset, OpenAI defaults to "auto" and picks the
            // output token budget itself — a ~15x per-image cost swing we'd have no control
            // over. Valid on /images/generations too, so the no-input reroute below is safe.
            ...(model_quality ? { quality: model_quality } : {}),
            size: "auto",         // scaffoldings are square today; revisit if aspect drift shows in QA
            output_format: "png"
        };
        // input_fidelity controls how finely the scaffolding is encoded (see the registry note).
        // Config-driven per tier, but only gpt-image-1.5 accepts it: gpt-image-1-mini 400s on
        // it, and gpt-image-2 rejects it too (always encodes inputs at high fidelity). It's
        // also meaningless without an input image. All three cases fall through to omitting it.
        if (inputImages.length && model_input_fidelity &&
            model_name !== "gpt-image-1-mini" && !String(model_name).startsWith("gpt-image-2")) {
            requestBody.input_fidelity = model_input_fidelity;
        }
        // /images/edits REQUIRES at least one input image. The DIRECT_IMAGE_GEN path arrives
        // with none, so reroute to the text-to-image endpoint (same body minus `images`,
        // same response shape, so Node 3 needs no extra branch).
        if (!inputImages.length) {
            model_url = model_url.replace("/images/edits", "/images/generations");
        }
    }
}

// Prepare output for the n8n HTTP Request Node
return [{
    json: {
        config,
        sessionState,
        sessionEvents,
        resolvedProvider,
        model_url,  // for API Call
        api_key: (config.api_keys && config.api_keys[resolvedProvider]),  // for API Call
        auth_mode: resolvedProvider === "openai" ? "bearer" : "query_key",  // routes the Node 2 provider switch
        requestBody,  // for API Call
        noModelResult,
        skipApi,  // for skip branch
        targetAgentId,
        currentTaskId,
        outputType,
        finalUserInstruction
    }
}];

// === 🐞 DEBUG TOGGLE ===
// When true, the return envelope also carries debug_system / debug_prompt / debug_response:
// plain-text views of the final templated system instruction, user instruction, and raw
// response text ("<IMAGE_BLOB>" for image-only responses). Off for normal runs: these are
// top-level fields, so any downstream "All Except" passthrough into a universal-agent call
// would sweep them into session_state unless the cfg nodes exclude them too.
const DEBUG_EMIT_IO = true;

// Render requestBody.contents as readable text: one block per contents entry (= one turn
// as the model sees it), boundary line carries the role. Text parts verbatim — including
// any "<agent> said:" labels and squashed multi-event text Node 1 baked in. Non-text
// parts become short tags; live image base64 (the current prompt's input image rides
// unsanitized in requestBody) is swapped for a tag, never dumped.
function renderContentsForDebug(contents) {
    if (!contents || !contents.length) return null;
    const renderPart = (p) => {
        if (p.text !== undefined) return p.text;
        const blob = p.inlineData || p.inline_data;
        if (blob) {
            const data = (typeof blob.data === "string" && blob.data.length > 100)
                ? "<IMAGE_BLOB>" : blob.data;
            return `[inline image: ${blob.mimeType || blob.mime_type || "?"} ${data}]`;
        }
        return JSON.stringify(p); // functionCall / functionResponse / fileData
    };
    return contents.map((c, i) =>
        `━━━━━━ turn ${i + 1} · role: ${c.role} ━━━━━━\n` + (c.parts || []).map(renderPart).join("\n")
    ).join("\n\n");
}

// === 📥 RECEIVE FROM NODE 1 ===
// Reach-back target: must equal the EXACT n8n node name of universal_agent_1_of_4.
const node1 = $("1. Prepare Payload").item.json; // ⚠️ confirm this matches your renamed node

const config = node1.config;
const sessionState = { ...(node1.sessionState || {}) };
const sessionEvents = node1.sessionEvents || [];
const resolvedProvider = node1.resolvedProvider;
const model_url = node1.model_url;  // for Cost Calculator
const noModelResult = node1.noModelResult;
const skipApi = node1.skipApi;
const agent_id = node1.targetAgentId || "Unknown Agent";
const task_id = node1.currentTaskId || "Unknown Task";
const outputType = node1.outputType || "text";

let geminiResponse = null;
if (!skipApi) {
    geminiResponse = items[0].json;
}

// === 🧼 SANITIZER (keep gigantic blobs out of logs/state) ===
// JSON.stringify replacer: swaps long base64 / thought-signature strings for tags.
function sanitize(key, value) {
    if (typeof value === "string" && value.length > 100) {
        if (key === "data" && (this.mimeType || this.mime_type)) return "<IMAGE_BLOB(Gemini)>";
        if (key === "b64_json") return "<IMAGE_BLOB(OpenAI)>";
        if (key === "base64_img_string") return "<IMAGE_BLOB>";
        if (key === "thoughtSignature") return "<THOUGHT_SIGNATURE>";
    }
    return value;
}

// Truncation helper for throw messages (keeps the error string useful but bounded).
const trunc = (s) => (s && s.length > 500 ? s.substring(0, 500) + "..." : s);

// === 🔎 PARSE THE OUTPUT ===
// Job of this section: build the one turnEvent for this turn (parts kept structural,
// sanitized), merge any parsed JSON fields into sessionState, and pull the image out to
// the top-level return only.
//
// ERROR POLICY: any malformed response (missing image, missing text, broken JSON) THROWS.
// A model that failed to respond properly can't be recovered by the pipeline anyway — the
// retry loops handle SEMANTIC failures (failed QA, bad code), which arrive as perfectly
// well-formed responses. Throwing drops us into the catch sub-workflow, which owns all
// failure reporting to the UI (via log_error → report_unknown_error). Node 3 itself never
// broadcasts a failure. Throw messages carry agent/task, finishReason where available, and
// a truncated raw dump — once we throw, that string is the only diagnostic that survives.
let parsedResult = null;       // merged into sessionState; null on the image path
let eventParts = null;         // becomes this turn's turnEvent.parts
let finalImageBase64 = null;   // top-level return only - not sessionState/turnEvent
let finalImageBase64_mimeType = null;

if (skipApi) {
    // --- PATH A: no_model. Synthesize a Gemini-shaped part, as if constrained generation sent it. ---
    // How the event text is rendered depends on which config key supplied the payload:
    //   result     → JSON.stringify, analogous to a model's constrained-JSON output
    //                (format_*_branch: the field names carry the structure).
    //   textResult → plain text, analogous to a model's prose output: "<name>: <value>"
    //                fields separated by newlines — or, for a single field, just the
    //                value with the name omitted (inject_constraints, log_error).
    // sessionState still gets the full named-field object either way.
    parsedResult = noModelResult;
    if (config.tasks[task_id]?.result === undefined && config.tasks[task_id]?.textResult !== undefined) {
        const entries = Object.entries(noModelResult || {});
        eventParts = [{
            text: entries.length === 1
                ? String(entries[0][1])
                : entries.map(([k, v]) => `${k}: ${typeof v === "string" ? v : JSON.stringify(v)}`).join("\n")
        }];
    } else {
        eventParts = [{ text: JSON.stringify(noModelResult) }];
    }

} else if (outputType === "image_blob" && (resolvedProvider || "google") === "openai") {
    // --- PATH B2: OpenAI image edit (/v1/images/edits). Response shape:
    //     { created, data: [{ b64_json }], output_format, usage } — GPT image models always
    //     return base64 (no URL mode); output_format ("png"/"jpeg"/"webp") gives the mime subtype.
    const b64 = geminiResponse?.data?.[0]?.b64_json;

    if (!b64) {
        // OpenAI errors arrive as { error: { message, type, ... } } rather than a data array.
        const apiMessage = geminiResponse?.error?.message || "no error message";
        throw new Error(`[${agent_id} / ${task_id}] No image in OpenAI response (${apiMessage}) — raw: ${trunc(JSON.stringify(geminiResponse))}`);
    }

    finalImageBase64 = b64;
    finalImageBase64_mimeType = "image/" + (geminiResponse.output_format || "png");
    // Synthesize a Gemini-shaped parts array so the event log stays uniform across providers
    // (Node 1's replay/resolveLogPart logic only ever sees one shape).
    eventParts = [{ inlineData: { mimeType: finalImageBase64_mimeType, data: "<IMAGE_BLOB(OpenAI)>" } }];

} else if (outputType === "image_blob") {
    // --- PATH B: Gemini image generation. Keep Gemini's own parts array, sanitized. ---
    const rawParts = geminiResponse?.candidates?.[0]?.content?.parts || [];
    const inlineData = (rawParts[0]?.inlineData || rawParts[0]?.inline_data);

    if (!inlineData?.data) {
        // Gemini returns HTTP 200 with no image when it blocks on safety or truncates —
        // finishReason (or promptFeedback.blockReason) distinguishes "model declined" from a bug.
        const finishReason = geminiResponse?.candidates?.[0]?.finishReason
            || geminiResponse?.promptFeedback?.blockReason || "none";
        throw new Error(`[${agent_id} / ${task_id}] No image in Gemini response (finishReason: ${finishReason}) — raw: ${trunc(rawParts[0]?.text || JSON.stringify(geminiResponse))}`);
    }

    finalImageBase64 = inlineData.data;
    finalImageBase64_mimeType = inlineData.mimeType || inlineData.mime_type;
    eventParts = JSON.parse(JSON.stringify(rawParts, sanitize));  // sanitize() swaps the long `data` string for <IMAGE_BLOB(Gemini)>

} else {
    // --- PATH C: standard JSON text response. Keep the real parts array, sanitized; parse the text. ---
    const rawParts = geminiResponse?.candidates?.[0]?.content?.parts;
    const rawText = rawParts?.[0]?.text;

    if (rawText === undefined) {
        const finishReason = geminiResponse?.candidates?.[0]?.finishReason
            || geminiResponse?.promptFeedback?.blockReason || "none";
        throw new Error(`[${agent_id} / ${task_id}] No text in Gemini response (finishReason: ${finishReason}) — raw: ${trunc(JSON.stringify(geminiResponse))}`);
    }

    // PARSE PROTECTION — parse-first, fence-extract on failure:
    //   1. Raw text that is already valid JSON parses untouched. This also guarantees a
    //      ``` inside a string VALUE can never trigger fence handling (the old global
    //      strip deleted every ``` in the text, including ones inside values).
    //   2. Only if the raw parse fails, extract the CONTENTS of the first fenced block
    //      and parse that. Stripping just the markers (old behavior) was useless against
    //      a preamble ("Here's the JSON: ```..."): the leftover prose crashed the parse
    //      anyway. Extraction recovers it.
    try {
        parsedResult = JSON.parse(rawText);
    } catch (rawErr) {
        const fenced = rawText.match(/```(?:json)?\s*([\s\S]*?)```/);
        if (!fenced) {
            throw new Error(`[${agent_id} / ${task_id}] JSON parse failed (${rawErr.message}) — raw: ${trunc(rawText)}`);
        }
        try {
            parsedResult = JSON.parse(fenced[1]);
        } catch (e) {
            throw new Error(`[${agent_id} / ${task_id}] JSON parse failed inside fence (${e.message}) — raw: ${trunc(rawText)}`);
        }
    }
    // Keep the real (sanitized) parts array - preserves multi-part responses
    // (e.g. text + functionCall) exactly as Gemini emitted them.
    eventParts = JSON.parse(JSON.stringify(rawParts, sanitize));
}

// === 🏷️ MODEL NAME RESOLUTION ===
// Human-readable model name stamped onto this turn's response event.
// OpenAI carries it in the request body; Gemini only in the URL (".../models/NAME:generateContent"),
// so we take the segment after the last "/" and before the ":". no_model turns get "none".
const modelName = skipApi
    ? "none"
    : (node1.requestBody?.model
        || (model_url ? model_url.substring(model_url.lastIndexOf("/") + 1).split(":")[0] : null));

// === 🧱 RECORD THIS TURN AS AN EVENT ===
// ADK style: one immutable event per turn, appended to the log. `eventParts` was already
// built + sanitized in the parse section above (no_model → JSON text; image → provider
// parts with the blob swapped for <IMAGE_BLOB>; JSON text → the real sanitized parts).
// The raw image is deliberately NOT in here — it rides along top-level only, like a
// temp:/artifact. status is always "ok": error turns throw before reaching this point,
// so every recorded event is by definition a good one (mirrors Node 1's prompt events).
const turnEvent = {
    author: agent_id,
    task: task_id,
    status: "ok",
    parts: eventParts,
    // actions - turnEvent.actions = { state_delta: parsedResult }  //  not using for now
    // partial: false,  //  to detect incomplete content chunks during real-time streaming - not used atm
    timestamp: new Date().toISOString(),
    model: modelName  // cost is injected after this field by the cost calculator below
};

// Append-only: build a new array, never mutate the inherited log.
const updatedSessionEvents = [...sessionEvents, turnEvent];

// === 🧠 MERGE PARSED FIELDS INTO SESSION STATE ===
// sessionState is the live, full-fidelity working memory Node 1 reads for {variable}
// templating, so parsed fields (reasoning, latest_description, etc.) must land here.
// Only the no_model and standard-JSON paths produce parsedResult; the image path leaves
// it null and adds nothing.
// (Guard skips strings/arrays so a stray string result can't get spread into state as
//  character-indexed keys. no_model results are expected to be objects of named fields.)
//
// HOISTED FIELDS: a task may list result keys in `hoist_result_fields`. These are big,
// single-use payloads (e.g. python_code) that a downstream node reads directly off this
// turn's output but that no prompt templates via {var}. We lift them to the top-level
// return and delete them from state, so they ride ONE hop to their consumer instead of
// being copied into every subsequent envelope's session_state. Same treatment as the
// image blob. The reviewers still see the value via scoped history (session_events).
const hoistKeys = config.tasks[task_id]?.hoist_result_fields || [];
const hoistedFields = {};
if (parsedResult && typeof parsedResult === "object" && !Array.isArray(parsedResult)) {
    Object.assign(sessionState, parsedResult);
    for (const k of hoistKeys) {
        if (k in sessionState) {
            hoistedFields[k] = sessionState[k];
            delete sessionState[k];
        }
    }
}

// === 🛑 TERMINAL MODE DETECTION ===
// Check if this task is configured to cleanly terminate the pipeline (success or failure).
// NOTE: terminal_mode is for PLANNED endings where an agent successfully wrote a message
// for the user. UNPLANNED endings (malformed responses) throw in the parse section above
// and are handled by the catch sub-workflow instead.
const terminalConfig = config.tasks[task_id]?.terminal_mode;
let jobStatus = "running";   // job-level pipeline status: "running" | "failed" | "completed"
let uiMessage = null;        // terminal agent's user-facing text (error_message / user_message)

if (terminalConfig) {  // has fields status & message_field
    jobStatus = terminalConfig.status || "failed";  // status[to GUI:failed/completed]
    uiMessage = parsedResult?.[terminalConfig.message_field];  // message_field[name of the field w/ user-facing message]
}

// === 📡 GUI PROGRESS BROADCAST (Fire & Forget) ===
// Keeps the ORIGINAL broadcast payload shape so the state-manager + Streamlit frontend keep
// working unchanged. Fields the flattened/ADK rewrite no longer carries get stand-ins:
//   - phase_id: "-"  (phases were flattened out of the config; the GUI just renders "Phase -")
//   - query:    falls back to the untemplated task instruction
// Only successful turns reach this point (error turns threw above), so `response` is
// either the sanitized parsed dict or the synthetic image-success object.
if (config.enable_gui_logging === true && config.gui_webhook_url) {

    let broadcastResponse;
    if (parsedResult && typeof parsedResult === "object") {
        broadcastResponse = JSON.parse(JSON.stringify(parsedResult, sanitize));
    } else if (finalImageBase64) {
        broadcastResponse = { status: "success", message: "Image generated successfully" };
    } else {
        broadcastResponse = parsedResult; // defensive fallback (not expected in practice)
    }

    // query: prefer the templated instruction if Node 1 forwards it, else the raw
    const broadcastQuery = node1.finalUserInstruction || config.tasks[task_id]?.instruction || "";

    try {
        const broadcastPayload = {
            job_id: config.job_id,
            phase_id: "-",                 // dummy: no phase in the flattened config
            agent_id: agent_id,
            task_id: task_id,
            query: broadcastQuery,
            response: broadcastResponse,
            status: jobStatus, // "running", "failed", or "completed"
            timestamp: new Date().toISOString(),
            ...(finalImageBase64 ? { base64_img_string: finalImageBase64 } : {})  // Attach the image string if one was generated
        };

        // If this is a terminal agent, attach the message for the frontend
        if (terminalConfig && uiMessage) {
            // Streamlit looks for 'error_message' if status is failed, and 'user_message' if completed
            if (jobStatus === "failed") broadcastPayload.error_message = uiMessage;
            else if (jobStatus === "completed") broadcastPayload.user_message = uiMessage;
        }

        await this.helpers.httpRequest({
            method: 'POST',
            url: config.gui_webhook_url,
            headers: { 'Content-Type': 'application/json' },
            body: broadcastPayload,
            json: true,
            timeout: 500
        });
    } catch (e) {
        // Fire-and-forget: never let a GUI logging failure break the pipeline.
        // Not forwarded downstream (would land in next-turn sessionState); logged locally instead.
        console.log(`GUI broadcast failed: ${e.message}`);
    }
}

// === 📦 ASSEMBLE OUTPUT ENVELOPE ===
// The state envelope returned to the parent orchestrator, which threads it into the next
// sub-workflow call. Mirrors the old `outputData` role, but ADK-shaped:
//   old `history`            → session_events (the append-only log built this turn)
//   old spread parsed fields → session_state  (already merged via Object.assign above; the
//                              next Node 1 reads {variables} from here, so they no longer
//                              need to be spread at top level)
//   old latest_description   → dropped: persistent session_state carries it forward on its
//                              own, so the old "keep it alive if not updated" hack is obsolete
// The raw image rides at top level as base64_img_string (NOT inside the log/state) so the
// next agent's Node 1 can attach it as an input image, exactly as the old file did.
const outputData = {
    config: config,
    session_state: sessionState,
    session_events: updatedSessionEvents,

    // Image passthrough (top-level only; kept out of session_state & session_events).
    // mime is required: Node 1 only attaches the image when BOTH string + mime are present.
    ...(finalImageBase64
        ? { base64_img_string: finalImageBase64, base64_img_string_mime: finalImageBase64_mimeType || "image/png" }
        : {}),

    // Hoisted heavy fields (e.g. python_code): top-level, single-hop, never in state.
    ...hoistedFields,

    // Debug I/O record: plain-text views of EXACTLY what the model saw this turn.
    //   debug_system   — final templated systemInstruction text (null if agent has none)
    //   debug_prompt   — the full requestBody.contents rendered readably: every turn the
    //                    model received (replayed history + current prompt), with role
    //                    boundaries between contents entries. Flattened/squashed events
    //                    and "<agent> said:" labels appear inline exactly as sent —
    //                    they're baked into the text parts by Node 1's flushQueue.
    //   debug_response — raw response text/JSON; "<IMAGE_BLOB>" if the model returned
    //                    only an image with no accompanying text
    ...(DEBUG_EMIT_IO
        ? {
            debug_system: node1.requestBody?.systemInstruction?.parts?.[0]?.text || null,
            // Gemini: rendered contents. OpenAI images: requestBody.prompt IS the literal
            // flat prompt sent (system text + flattened history + instruction, one string).
            debug_prompt: renderContentsForDebug(node1.requestBody?.contents)
                ?? node1.requestBody?.prompt ?? node1.finalUserInstruction ?? null,
            debug_response: skipApi
                ? JSON.stringify(noModelResult)
                : (geminiResponse?.candidates?.[0]?.content?.parts?.find(p => p.text !== undefined)?.text
                    ?? (finalImageBase64 ? "<IMAGE_BLOB>" : null))
          }
        : {}),
};


// ============================================================================
// 💰 COST CALCULATION  (inlined from universal_agent_4_of_4_Cost_Calculator.js)
// Appended here instead of running as a separate downstream node so the raw image
// blob never has to survive a sub-workflow hop. Calculations below are unchanged.
// ============================================================================

// use with usageMetadata & groundingMetadata to calculate costs
const cost_registry = {
  "https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-pro-preview:generateContent": {
    input: 2.00,
    output_text: 12.00,
    contextThreshold: 200000,
    input_over_threshold: 4.00,
    output_text_over_threshold: 18.00,
    cache_read: 0.20,
    cache_read_over_threshold: 0.40,
    cache_storage_hourly: 4.50,
    grounding_search_per_1k: 14.00,  // A customer-submitted request to Gemini may result in one or more queries to Google Search. You will be charged for each individual search query performed.
    grounding_maps_per_1k: 14.00
  },
  "https://generativelanguage.googleapis.com/v1beta/models/gemini-3.6-flash:generateContent": {
    input: 1.50,
    output_text: 7.50,
    cache_read: 0.15,
    cache_storage_hourly: 1.00,
    grounding_search_per_1k: 14.00,  // A customer-submitted request to Gemini may result in one or more queries to Google Search. You will be charged for each individual search query performed.
    grounding_maps_per_1k: 14.00
  },
  "https://generativelanguage.googleapis.com/v1beta/models/gemini-3.5-flash-lite:generateContent": {
    input_default: 0.30, // single rate across text / image / video / audio (unlike 3.1 lite, no audio surcharge)
    input_audio: 0.30,
    output_text: 2.50,
    cache_read_default: 0.03,
    cache_read_audio: 0.03,
    cache_storage_hourly: 1.00,
    grounding_search_per_1k: 14.00,
    grounding_maps_per_1k: 14.00
  },
  // --- Gemini image models (img2img tiers slow / medium / fast) ---
  "https://generativelanguage.googleapis.com/v1beta/models/gemini-3-pro-image:generateContent": {
    // Inherits base text/image properties from Gemini 3.1 Pro
    input: 2.00,
    output_text: 12.00,
    output_image: 120.00,   // 1120 tokens ⇒ ~$0.134 per 1K/2K image; 2000 tokens ⇒ ~$0.24 at 4K
    grounding_search_per_1k: 14.00
  },
  "https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-image:generateContent": {
    input: 0.50,
    output_text: 3.00,
    output_image: 60.00,    // 1120 tokens ⇒ ~$0.067 per 1K image
    grounding_search_per_1k: 14.00
  },
  "https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-lite-image:generateContent": {
    input: 0.25,
    output_text: 1.50,
    output_image: 30.00     // 1120 tokens ⇒ ~$0.0336 per 1K image
    // No grounding rates published for this model.
  },

  // --- Superseded Gemini models: no longer routed to by the config registry, kept so cost
  //     lookup still works if a tier is pointed back at them. (Scope ends at the OpenAI
  //     block below, which has its own active/retired split.) ---
  "https://generativelanguage.googleapis.com/v1beta/models/gemini-3.5-flash:generateContent": {
    input: 1.50,
    output_text: 9.00,
    cache_read: 0.15,
    cache_storage_hourly: 1.00,
    grounding_search_per_1k: 14.00,  // A customer-submitted request to Gemini may result in one or more queries to Google Search. You will be charged for each individual search query performed.
    grounding_maps_per_1k: 14.00
  },
  "https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-lite:generateContent": {
    input_default: 0.25, // text, image, video
    input_audio: 0.50,   // double rate for audio
    output_text: 1.50,
    cache_read_default: 0.025,
    cache_read_audio: 0.05,
    cache_storage_hourly: 1.00,
    grounding_search_per_1k: 14.00,
    grounding_maps_per_1k: 14.00
  },
  "https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash-image:generateContent": {
    input: 0.30,
    output_text: 2.50,   // Matched to base 2.5 Flash text output rate
    output_image: 30.00  // 1290 tokens ⇒ ~$0.039 per 1024x1024 image
  },
  // --- OpenAI image models (keyed by MODEL NAME, not URL: all tiers share
  //     /v1/images/edits; lookup falls back to requestBody.model below). Rates
  //     are $/1M tokens split by modality, matching the usage.*_tokens_details shape.
  //     Verified against the official model pricing pages 2026-08-04.
  //
  //     NOTE: these are RATES, not per-image prices — the per-image cost is driven by the
  //     `quality` tier set in the config registry, which decides how many output tokens get
  //     spent (per square image, gpt-image-2 ≈ $0.006 / $0.053 / $0.211 at low / medium /
  //     high; gpt-image-1.5 ≈ $0.009 / $0.034 / $0.133). gpt-image-2 also always encodes
  //     input images at high fidelity (extra input tokens, no opt-out; on 1.5 the same
  //     effect is the opt-in input_fidelity="high" block, ~$0.033/call). All of it lands in
  //     usage.*_tokens_details, so the math below already captures it; it just isn't
  //     visible in the rate table. ---
  // Image-output only — text output is unpriced ("-" on the pricing page), hence no
  // output_text key.
  "gpt-image-2": {
    input_text: 5.00,
    input_image: 8.00,
    output_image: 30.00
  },
  // --- Not currently routed to (all three OpenAI tiers run gpt-image-2 and vary `quality`),
  //     kept so the lookup still prices correctly if a tier is pointed back at them.
  //     Mini is image-output only like gpt-image-2; 1.5 does publish a text output rate. ---
  "gpt-image-1.5": {
    input_text: 5.00,
    input_image: 8.00,
    output_text: 10.00,
    output_image: 32.00
  },
  "gpt-image-1-mini": {
    input_text: 2.00,
    input_image: 2.50,
    output_image: 8.00
  }
};

// --- EXECUTION ENGINE ---
// Inlined I/O: read locals directly instead of a downstream node's $input payload.
// (outputData was assembled above; model_url/usage/grounding are already in scope.)
const modelUrl = model_url;
const requestModel = node1.requestBody?.model || null;  // OpenAI carries the model in the body, not the URL
const usage = geminiResponse?.usageMetadata || {};
const grounding = geminiResponse?.groundingMetadata || {};

let taskCost = 0;
const pricing = cost_registry[modelUrl] || (requestModel ? cost_registry[requestModel] : undefined);

if (pricing && geminiResponse?.usage?.input_tokens_details) {  // OpenAI
    // --- OpenAI images usage shape: flat modality splits, no per-detail arrays,
    //     no context-window threshold, no grounding fees on this endpoint. ---
    const u = geminiResponse.usage;
    const inText  = u.input_tokens_details?.text_tokens ?? 0;
    const inImage = u.input_tokens_details?.image_tokens ?? 0;
    const outText  = u.output_tokens_details?.text_tokens ?? 0;
    const outImage = u.output_tokens_details?.image_tokens ?? (u.output_tokens ?? 0);

    taskCost = (inText  / 1000000) * (pricing.input_text   ?? 0)
             + (inImage / 1000000) * (pricing.input_image  ?? 0)
             + (outText  / 1000000) * (pricing.output_text  ?? 0)
             + (outImage / 1000000) * (pricing.output_image ?? 0);

} else if (pricing) {  // Gemini
    const totalPromptTokens = usage.promptTokenCount ?? 0;
    const totalTokens = usage.totalTokenCount ?? 0;

    // Evaluate Context Window Threshold
    const threshold = pricing.contextThreshold ?? 0;
    const isOverThreshold = threshold > 0 && totalTokens > threshold;

    // Calculate Input Tokens
    let inputCost = 0;
    const promptDetails = usage.promptTokensDetails || [{ modality: "TEXT", tokenCount: totalPromptTokens }];

    for (const detail of promptDetails) {
        const modality = (detail.modality ?? "TEXT").toLowerCase();
        const tokenCount = detail.tokenCount ?? 0;
        if (tokenCount === 0) continue;

        let baseInputRate = null;
        if (pricing.input !== undefined) {
            baseInputRate = pricing.input;
        } else if (pricing[`input_${modality}`] !== undefined) {
            baseInputRate = pricing[`input_${modality}`];
        } else if (pricing.input_default !== undefined) {
            baseInputRate = pricing.input_default;
        } else {
            throw new Error(`Billing Error: No input rate found for model ${modelUrl} (Modality: ${modality})`);
        }

        if (isOverThreshold) {
            baseInputRate = pricing.input_over_threshold ?? (baseInputRate * 2);
        }
        inputCost += (tokenCount / 1000000) * baseInputRate;
    }

    // Calculate Output Tokens
    let outputCost = 0;
    const candidateDetails = usage.candidatesTokensDetails || [{ modality: "TEXT", tokenCount: usage.candidatesTokenCount ?? 0 }];

    for (const detail of candidateDetails) {
        const modality = (detail.modality ?? "TEXT").toLowerCase();
        const tokenCount = detail.tokenCount ?? 0;
        if (tokenCount === 0) continue;

        let baseOutputRate = 0;
        if (modality === "text") {
            baseOutputRate = pricing.output_text ?? 0;
            if (isOverThreshold) {
                baseOutputRate = pricing.output_text_over_threshold ?? (baseOutputRate * 2);
            }
        } else if (modality === "image") {
            baseOutputRate = pricing.output_image ?? 0;
        } else {
            baseOutputRate = pricing[`output_${modality}`] ?? pricing.output_text ?? 0;
        }

        outputCost += (tokenCount / 1000000) * baseOutputRate;
    }

    // Calculate Grounding Search Fees
    let groundingCost = 0;
    if (grounding.webSearchQueries && Array.isArray(grounding.webSearchQueries)) {
        const searchQueriesCount = grounding.webSearchQueries.length;
        const searchRatePer1k = pricing.grounding_search_per_1k ?? 0;
        groundingCost = (searchQueriesCount / 1000) * searchRatePer1k;
    }

    taskCost = inputCost + outputCost + groundingCost;
}

// 2. Inject ONLY the final cost into the most recent record.
//    (old target: outputData.history[last]; new target: this turn's session_event)
if (outputData.session_events && outputData.session_events.length > 0) {
    outputData.session_events[outputData.session_events.length - 1].cost = Number(taskCost.toFixed(6));
}

// 3. Return ONLY the outputData. Billing metadata (modelUrl/usage/grounding) stays local
//    and is never bundled into the return, so nothing extra crosses the sub-workflow boundary.
return [{ json: outputData }];
